-- c010-v004: msi chukue mfuko–wa–pesa wala mkoba wala viatu na yeyote katika hiyo njia msisalimu
-- c010-v005: Katika yoyote na iwe mtaingia nyumba kwanza semeni Amani kwa–hii nyumba hii
-- c010-v006: na ikiwa huko yupo mwana wa–amani itakaa juu–yake yeye hiyo amani yenu lakini–ikiwa na hapana juu–yenu ninyi itarudi
-- c010-v007: Katika hiyo na hiyo nyumba kaeni mkila na mkunywa vitu kutoka–kwao wao anastahili kwa–maana huyo mfanyakazi wa mshahara wake Msi hamie kutoka nyumba kwa nyumba
-- c010-v008: Na katika wowote iwe mji mtaingia na watakapowapokea ninyi kuleni vile vinavyowekwa–mbele–yenu ninyi
-- c010-v009: na waponyeni hao ndani–yake humo wagonjwa na waambieni wao Imekaribia juu–yenu ninyi huo ufalme wa Mungu
-- c010-v010: Katika wowote na iwe mji mtaingia na hawata kuwapokea ninyi mkitoka kwa zile barabara–kubwa zake semeni
-- c010-v011: Hata ule mavumbi ule ulioshika sisi kutoka katika–huo mji wenu kwa hizo miguu tunajifuta ninyi lakini hili jueni kwamba umekaribia huo ufalme wa Mungu
-- c010-v012: ninasema kwenu kwamba kwa–Sodoma katika siku ile ile kutavumilika–zaidi itakuwa kuliko kwa–huo mji ule
-- c010-v013: Ole wako Chorazín ole wako Bēthsaïdá kwa–maana kama katika Týros na Sidṓn zilifanyika hizo nguvu zile zilizofanyika kwenu ninyi zamani wangeli katika gunia na majivu wakikaa walitubu
-- c010-v014: Lakini kwa–Týros na Sidṓn kutavumilika–zaidi itakuwa katika hiyo hukumu kuliko ninyi
-- c010-v015: Na wewe Kapharnaoúm je hadi mbingu utainuliwa hadi kuzimu kuzimu utashushwa
-- c010-v016: Yule anayewasikia ninyi mimi anasikia na yule anayewakataa ninyi mimi anakataa yule na mimi anayenikataa anamkataa huyo aliyenituma mimi
-- c010-v017: Walirudi na hao sabini wawili na furaha wakisema Bwana hata hayo mapepo yanatii sisi katika hilo jina lako
-- c010-v018: akawaambia na wao Nilimwona huyo Satanâs kama umeme kutoka katika mbingu akianguka
-- c010-v019: Tazama nimewapa ninyi hiyo mamlaka ya kukanyaga juu–ya nyoka na nge na juu–ya uwezo–wote wa–huyo uwezo wa–huyo adui na hakuna–kitu ninyi kamwe si kitawadhuru
-- c010-v020: Lakini katika hili msi furahie kwamba hizo roho ninyi zinawatii furahini lakini kwamba hayo majina yenu yameandikwa katika hizo mbingu
-- c010-v021: Katika ile ile saa alifurahi–sana katika huyo Roho huyo Mtakatifu na akasema Ninakushukuru Wewe Baba Bwana wa mbingu na wa–dunia dunia kwamba umeficha haya kutoka–kwa wenye–hekima na wenye–akili na umeyafunua hayo kwa–watoto–wachanga ndiyo huyo Baba kwa–maana hivyo mapenzi–mema yalikuwa mbele–yako wewe
-- c010-v022: Vitu–vyote mimi vimekabidhiwa na huyo Baba wangu na hakuna–mtu anajua nani ni huyo Mwana isipokuwa si huyo Baba na nani ni huyo Baba isipokuwa si huyo Mwana na yeyote ambaye anapenda huyo Mwana kumfunulia
-- c010-v023: Na akigeuka kwa hao wanafunzi faragha peke–yake akasema Wamebarikiwa hizo macho hizo yanayoona yale mnayoyaona
-- c010-v024: ninawaambia kwa–maana ninyi kwamba wengi manabii na wafalme walitaka kuona yale ninyi mnayoona na hawaku yaona na kusikia yale mnayosikia na hawaku yasikia
-- c010-v025: Na tazama mwanasheria mmoja alisimama akimjaribu yeye akisema Mwalimu nini nikifanya uzima wa–milele nitaurithi
