-- c010-v028: Akamwambia na yeye Sawasawa umejibu Hili fanya na utaishi
-- c010-v029: Yeye lakini akitaka kujihesabia–haki mwenyewe akamwambia kwa huyo Iēsoûs Na nani ni wangu jirani
-- c010-v030: Akijibu na huyo Iēsoûs akasema Mtu mmoja alikuwa–akishuka kutoka Hierousalḗm kwenda Ierichṓ na wanyang'anyi akaangukia ambao pia wakimvua yeye na majeraha wakimtia wakaondoka wakimwacha nusu–mfu
-- c010-v031: Kwa–bahati mbaya na kuhani mmoja alikuwa–akishuka katika ile njia ile na akimwona yeye akapita–upande–mwingine
