-- c010-v035: Na kesho–yake hiyo kesho akitoa dinari mbili akampa huyo mwenye–nyumba–ya–wageni na akasema Mtunze yeye na chochote kitu iwe utakachotumia–zaidi mimi wakati wa–kurudi kurudi kwangu nitakulipa wewe
-- c010-v036: Yupi kati–ya–hawa hao watatu jirani unadhani wewe alikuwa kwa–huyo aliyeangukia kwa hao wanyang'anyi
-- c010-v037: Yeye na akasema Yule aliyemfanyia hiyo huruma na yeye Akamwambia na yeye huyo Iēsoûs Nenda na wewe fanya vivyo–hivyo
-- c010-v038: Katika na huko kusafiri wao yeye aliingia katika kijiji kimoja mwanamke na mmoja jina–lake Mártha alimpokea yeye katika hiyo nyumba
-- c010-v039: na huyu alikuwa–na dada aitwaye Mariám ambaye pia akiketi karibu–na hizo miguu ya–huyo Bwana alimsikia hilo neno lake
